        (100, 0, 3, [(33, 0, 33), (33, 0, 33), (34, 0, 34)]),
        (0, 500, 2, [(0, 0, 0), (0, 0, 0)]),
        (5000, 0, 1, [(5000, 0, 5000)]),
        (10000, 1200, 1, [(10100, 100, 10000)]),
        (200, 0, 3, [(67, 0, 67), (67, 0, 67), (66, 0, 66)]),
        (99, 0, 2, [(50, 0, 50), (49, 0, 49)]),
    ],
)
def test_examples(p, bp, m, expected):
